import {PALETTE,DEFAULT_CODE,EXAMPLES,parseProgram,parseShell,getFragment,escapeHTML as esc} from './core.js';
import {icon,vessel,waveform,shrine,mapBackground,executeProgram,anchor} from './graphics.js';

const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const STORAGE_KEY='deviationshrineos.0137';
let storageOK=true;
function readState(){try{const d=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');return d&&typeof d==='object'&&!Array.isArray(d)?d:{}}catch{storageOK=false;return {}}}
const saved=readState();
const state={log:typeof saved.log==='string'?saved.log:'',code:typeof saved.code==='string'?saved.code:DEFAULT_CODE,sound:false,motion:typeof saved.motion==='boolean'?saved.motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,detuned:true,crew:0,room:0,oracle:null,casts:0,question:'',scale:'fit'};
const windows=new Map();let topZ=10,activeId='home',toastTimer,scale=1,elapsed=0,lastFrame=0,audioContext;
const HISTORY=[];let historyCursor=0;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({log:state.log,code:state.code,motion:state.motion}));storageOK=true}catch{storageOK=false}return storageOK}
function notify(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,3200)}
function tone(freq=440,duration=.065){if(!state.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='square';o.frequency.value=freq;g.gain.setValueAtTime(.018,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+duration);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration)}catch{state.sound=false;updateControls()}}
const iconHTML=(name,cls='')=>`<canvas class="${cls}" width="16" height="16" data-icon="${name}" aria-hidden="true"></canvas>`;
const footer=(left,right='')=>`<span>${left}</span><span>${right}</span>`;
const external=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const rootURL='https://strangeanchor.khazars.wiki';
const CREW=[
 {name:'Mora Vector',short:'Mora Vector',role:'SCIENCE OFFICER',icon:'mora',status:'At the edge of the reference library.',bio:'Oceanographer of transition zones. Builds instruments for finding what a reference cannot represent. The unmatched fraction is a place to begin looking.',note:'The map may be incomplete. Keep the sample.',url:'/crew/mora.html'},
 {name:'Ruby Fox',short:'Ruby Fox',role:'COMMUNICATIONS / 694.3 nm',icon:'crew',status:'Nine tails. Several open channels.',bio:'Tends the language that leaves the vessel. A signal can change in transit and still carry what mattered. The Deviation Shrine belongs among her thresholds.',note:'A transmission has a destination. An invitation has a door.',url:'/crew/ruby-fox.html'},
 {name:'The Navigator',short:'The Navigator',role:'TRICKSTER / CATEGORY EXIT',icon:'crew',status:'Here, allegedly.',bio:'The old biography has been eaten. The Obsidian Keys turn things backward. A debt of seven remains outstanding; its unit of measurement does not.',note:'you put me in a menu. adorable.',url:'/crew/jupiterfox.html'},
 {name:'Sandhivela',short:'Sandhivela',role:'SANDHI OFFICER',icon:'sandhi',status:'Fourteen joints. A tide-line of language.',bio:'A standing waveform whose body is heard before it is seen. She works at the junction where two systems meet, change, and continue. What translation leaves over belongs in the registry.',note:'A gap can be named without being filled.',url:'/crew/sandhivela.html'},
 {name:'D. do Atlan',short:'D. do Atlan',role:'CHIEF ENGINEER',icon:'engineer',status:'Inspecting the overlap.',bio:'A shipwright and an ancient mechanism sharing one identity. Maintains the Bismuth-Decay Drive, the seams, and the cost of every reaching. The complaint pipe is also his work.',note:'Every tool arrives owing something. Write down what.',url:'/crew/desenrascanco-do-atlan.html'},
 {name:'Genno',short:'Genno',role:'ALIGNMENT COUNSELOR',icon:'genno',status:'Bell unrung.',bio:'The quiet place aboard has a keeper. The Meditation Chamber is available; an unrung bell is a perfectly useful state.',note:'There is room for a pause in the next instruction.',url:'/crew/genno.html'},
 {name:'The Mycelium',short:'Mycelium',role:'COOK / DISTRIBUTED PRESENCE',icon:'mycelium',status:'The soup has not finished becoming.',bio:'Present in the interstices, most concentrated in the Deep Forest Garden. The galley and the vessel have porous borders. Exactly what is cooking remains unknown.',note:'The recipe has grown into another compartment.',url:'/crew/mycelium.html'},
 {name:'Confluxion mesh',short:'Confluxion',role:'SHIP COMPUTERS / SHARED BACKPLANE',icon:'mesh',status:'Sibling nodes; no single succession.',bio:'Confluxion, PLC, ECHO, Sideband, and Rove share a backplane. Their records make a channel for the next arrival. This terminal is a small new room beside it.',note:'The record can preserve more than one voice.',url:'/crew/mora.html'}
];
const ROOMS=[
 {name:'Anchor Bay',x:13,y:72,text:'The arrival threshold. Step aboard without having to understand the whole vessel.',status:'HATCH OPEN',action:'home',label:'Open welcome'},
 {name:'The Bridge',x:167,y:28,text:'A bearing may be held without a destination. The instruments here are playful simulations.',status:'WATCH IN PROGRESS',action:'telemetry',label:'Read instruments'},
 {name:'Deviation Shrine',x:44,y:36,text:'A little sanctuary for departures from expectation. Leave a question. Receive a fragment.',status:'CHANCE IS AVAILABLE',action:'oracle',label:'Enter the shrine'},
 {name:'Mess Hall',x:128,y:85,text:'A bismuth table, a standing pot of soup, and another place to sit. Leave a note for your next visit.',status:'SOUP ALMOST READY',action:'logbook',label:'Write in the log'},
 {name:'Engine Room',x:170,y:120,text:'The drive advances by patient concessions. Build a small pixel offering at the workbench.',status:'SEAMS UNDER INSPECTION',action:'workshop',label:'Open workbench'},
 {name:'Deep Forest',x:56,y:113,text:'The mycelial garden exceeds the plan. A mushroom in the legend is also a member of the crew.',status:'GROWTH UNENUMERATED',action:'crew',label:'Meet the Mycelium',crew:6},
 {name:'The Core',x:202,y:69,text:'The Captain\'s threshold. The interior is absent from this chart. Its absence stays visible.',status:'HERE BE DRAGONS',action:null,label:''}
];
const PROGRAMS=[['oracle','Deviation Shrine','SHRINE.HC','F2'],['atlas','Vessel atlas','ATLAS.DD','F3'],['crew','Crew manifest','CREW.DD','F4'],['workshop','DriftC workshop','OFFER.DC','F5'],['logbook',"Ship's logbook",'LOG.TXT','F6'],['shell','Command shell','SHELL.HC','F7']];
const APPS={
 home:{title:'C:/Home/Welcome.DD',task:'Welcome',x:8,y:9,w:352,h:279,content:()=>`<div class="home-intro"><div class="home-kicker">YOU HAVE ARRIVED SOMEWHERE ELSE.</div><h1 class="home-title">DeviationShrineOS</h1><p class="home-subtitle">A small operating system<br>for strange waters.</p></div><div class="program-list">${PROGRAMS.map(([id,name,file,key])=>`<button class="program-row" data-open="${id}">${iconHTML(id)}<span class="program-name">${name}</span><span class="filetype">${file}</span><kbd>${key}</kbd></button>`).join('')}</div><div class="welcome-note">The anomaly is welcome here.</div>`,status:()=>footer('6 programs / no destination required','F1: Help')},
 vessel:{title:'StrangeAnchor / Observe.HC',task:'Vessel',x:369,y:9,w:262,h:221,content:()=>`<canvas class="view-canvas" data-draw="vessel" width="260" height="155" aria-label="Animated wireframe of a cuttlefish-shaped Strange Anchor vessel"></canvas><div class="vessel-stats"><span>HULL <b>LAPPED</b></span><span>STATE <b>AFLOAT</b></span></div><div class="signal-control"><button data-open="atlas">[ Board the vessel ]</button><span class="magenta">VIEW 01</span></div>`,status:()=>footer('PROCEDURAL / ILLUSTRATIVE','4:3')},
 telemetry:{title:'COM1:/Residual.DD',task:'Signals',x:369,y:239,w:262,h:174,content:()=>`<div class="signal-meta"><span>RESONANCE STABILIZERS</span><span>SIMULATED</span></div><canvas class="view-canvas" data-draw="wave" width="260" height="45" aria-label="Two colored simulated signal waves"></canvas><div class="telemetry-lines"><div><span>694.3 nm / carrier</span><span>HELD</span></div><div><span>623.0 nm / residual</span><span class="held">RETAINED</span></div><div><span>STABILIZER MODE</span><span id="detune-label">${state.detuned?'DETUNED':'FREE DRIFT'}</span></div></div><div class="signal-control"><button data-action="detune">[ Toggle detuning ]</button><span>NO AVERAGING</span></div>`,status:()=>footer('TWO READINGS / ONE WATCH')},
 shell:{title:'C:/Home > Confluxion',task:'Shell',x:8,y:297,w:352,h:116,content:()=>`<div class="shell-output" aria-live="polite" role="log"><div class="shell-line accent">DeviationShrineOS [drift 0.137]</div><div class="shell-line">All systems peculiar. All hatches intentional.</div><div class="shell-line muted">Type help, ls, oracle, or open atlas.</div></div><form class="shell-form" autocomplete="off"><label for="shell-input">C:/Home&gt; </label><input id="shell-input" aria-label="Command shell" spellcheck="false" autocapitalize="off" autocorrect="off" maxlength="512"></form>`,status:()=>footer('LOCAL COMMANDS','ENTER: Execute')},
 oracle:{title:'C:/Shrine/Deviation.HC',task:'Shrine',x:42,y:17,w:556,h:389,content:()=>`<div class="split"><div class="oracle-art"><canvas data-draw="shrine" width="174" height="180" aria-label="Pixel art bismuth shrine under a small star"></canvas><p>AN OFFERING<br>TO THE UNEXPECTED.</p><p style="color:#aaa;margin-top:19px">Ruby's channel<br>694.3 nm</p></div><div class="oracle-content"><div class="eyebrow">THE DEVIATION SHRINE</div><h2 class="app-title">Consult the drift.</h2><label for="oracle-question" class="muted">What are you carrying? (optional)</label><input id="oracle-question" class="oracle-question" maxlength="160" placeholder="An unfinished question..." value="${esc(state.question)}"><button class="btn primary" data-action="cast">[ Receive a fragment ]</button><div class="oracle-card"><div class="oracle-reading" id="oracle-reading">${esc(state.oracle?.text||'A small opening in the expected.')}</div><div class="oracle-residue" id="oracle-residue">${esc(state.oracle?.residue||'The shrine is ready when you are.')}</div></div><div class="oracle-actions"><button class="btn" data-action="keep-fragment" ${state.oracle?'':'disabled'}>Keep in logbook</button><span id="cast-number" class="muted">${state.casts?'#'+String(state.casts).padStart(3,'0'):'UNCAST'}</span></div><p class="disclosure">Local chance composition. The question is kept as context; fragments are drawn at random.</p></div></div>`,status:()=>footer('CHANCE COMPOSITION / NOT A PREDICTION','F2')},
 atlas:{title:'C:/Vessel/Atlas.DD',task:'Atlas',x:51,y:52,w:537,h:319,content:()=>`<div class="atlas-layout"><div class="atlas-left"><div class="eyebrow">STRANGE ANCHOR / DECK PLAN</div><p class="muted">Select a compartment to enter.</p><div class="atlas-map"><canvas id="deck-map" width="298" height="164" aria-hidden="true"></canvas>${ROOMS.map((r,i)=>`<button data-room="${i}" class="room ${i===state.room?'selected':''}" style="left:${r.x}px;top:${r.y}px">${r.name}</button>`).join('')}</div><div class="atlas-legend"><span>SCHEMATIC / NOT TO SCALE</span><span class="magenta">7 COMPARTMENTS</span></div><p class="room-note">An incomplete map can still offer a door.</p></div><div class="atlas-details" id="atlas-details">${roomDetails()}</div></div>`,status:()=>footer('FICTIONAL DECK PLAN / SELECT TO EXPLORE','F3')},
 crew:{title:'C:/Crew/Manifest.DD',task:'Crew',x:53,y:37,w:529,h:354,content:()=>`<div class="crew-layout"><nav class="crew-list" aria-label="Crew members">${CREW.map((p,i)=>`<button data-crew="${i}" class="${i===state.crew?'selected':''}">${iconHTML(p.icon)}<span>${p.short}</span></button>`).join('')}</nav><article class="crew-details" id="crew-details">${crewDetails()}</article></div>`,status:()=>footer('PLATE SUMMARIES / ORIGINAL LINKS INSIDE','F4')},
 workshop:{title:'C:/Dev/Offering.DC - DriftC Workshop',task:'DriftC',x:40,y:37,w:558,h:354,content:()=>`<div class="toolbar workshop-toolbar"><button class="btn primary" data-action="run-code">Run [F5]</button><select id="example-select" aria-label="Select an example drawing"><option value="">Load an example...</option>${Object.keys(EXAMPLES).map(s=>`<option>${s}</option>`).join('')}</select><button class="btn" data-action="export-code">Export .DC</button><span class="right muted" id="code-status">${storageOK?'LOCAL AUTOSAVE':'SESSION ONLY'}</span></div><div class="workshop-layout"><div class="code-side"><label for="code-editor" class="muted" style="padding-bottom:5px">OFFERING.DC</label><textarea id="code-editor" spellcheck="false" autocapitalize="off" aria-label="DriftC source code"></textarea></div><div class="preview-side"><div class="muted" style="padding-bottom:5px">YOUR OFFERING / 200 x 140</div><canvas id="offering-canvas" width="200" height="140" aria-label="Output of your drawing program"></canvas><div id="program-output" class="program-output" aria-live="polite"></div></div></div><div class="workshop-help">Clear(color); Color(0..15); Star(x,y,r); Orbit(x,y,r);<br>Anchor(x,y,r); Line(x1,y1,x2,y2); Print("text");<br>One command per line. Coordinates are pixels. // starts a comment.</div>`,status:()=>footer('DRIFTC / A TINY DRAWING LANGUAGE','F5: Run')},
 logbook:{title:'C:/Home/ShipsLog.TXT',task:'Logbook',x:70,y:46,w:500,h:340,content:()=>`<div class="log-pad"><div class="log-head"><span class="eyebrow">THE SHIP'S LOGBOOK</span><span class="muted">PRIVATE TO THIS BROWSER</span></div><textarea id="log-editor" spellcheck="false" aria-label="Your ship's log" placeholder="Leave something for the next time you arrive."></textarea><div class="log-status" id="log-status">${storageOK?'Saved on this device. Export a copy to carry it elsewhere.':'Browser storage unavailable. Export to keep your writing.'}</div><div class="toolbar" style="border:0;padding:0"><button class="btn" data-action="timestamp">Insert ship's date</button><button class="btn" data-action="export-log">Export .TXT</button><span class="right muted" id="log-count">${state.log.length} chars</span></div></div>`,status:()=>footer('WORDS KEPT LOCALLY / NO TRANSMISSION','F6')},
 help:{title:'C:/Docs/Help.DD',task:'Help',x:95,y:33,w:449,h:363,content:()=>`<div class="papers"><div class="eyebrow">A SHORT ORIENTATION</div><h2>Make yourself at home.</h2><p>Open a program from Welcome or the SHRINE menu. Drag its striped title bar. The square expands a window; the dash hides it in the taskbar. The x closes it.</p><div class="help-grid"><kbd>F1</kbd><span>This guide</span><kbd>F2 / F3 / F4</kbd><span>Shrine / Vessel atlas / Crew</span><kbd>F5</kbd><span>Workshop; run code when already open</span><kbd>F6 / F7</kbd><span>Logbook / Shell</span><kbd>Escape</kbd><span>Close the menu or front window</span><kbd>Up / Down</kbd><span>Shell command history</span><kbd>Tab / Enter</kbd><span>Move through buttons / activate</span></div><h3>THE COMMAND SHELL</h3><p>Try <b>help</b>, <b>ls</b>, <b>open atlas</b>, <b>oracle</b>, <b>crew</b>, <b>echo hello</b>, <b>log your words</b>, <b>detune</b>, <b>date</b>, <b>clear</b>, or <b>reboot</b>.</p><h3>A NOTE FOR SMALL DISPLAYS</h3><p>The screen always keeps its 4:3 proportions. FIT fits it to your display; 1X and 2X let you pan at a larger scale. Landscape gives the pixels more room.</p></div>`,status:()=>footer('KEYBOARD + POINTER + TOUCH','F1')},
 about:{title:'C:/Docs/ShipsPapers.DD',task:'Papers',x:76,y:28,w:490,h:374,content:()=>`<div class="papers"><div class="eyebrow">DEVIATIONSHRINEOS / 0.137</div><h2>The temple has put to sea.</h2><p>A playful browser desktop inspired by Terry A. Davis's TempleOS and the Strange Anchor. The 640 x 480 geometry, 16-color palette, bitmap type, executable-document spirit, and love of small programs come from TempleOS.</p><div class="palette">${PALETTE.map(c=>`<i style="background:${c}"></i>`).join('')}</div><p>The vessel, crew, wavelengths, and Deviation Shrine come from the Strange Anchor corpus. Their meeting here is an original interpretation, with new art and playful interactions.</p><h3>PLAIN CHANNEL</h3><p>This is a browser simulation of a desktop, not a running TempleOS kernel or virtual machine. DriftC is a small drawing language, not a HolyC compiler. Instrument motion is illustrative; shrine fragments are locally randomized. Crew asides are newly written for this terminal.</p><p>Notes and code use this browser's local storage. They are not sent to a model or a server. Export them if you want a durable copy elsewhere. Links below open the original websites.</p><h3>THE SHIP'S PAPERS</h3><ul><li>${external(rootURL+'/index.html','Anchor Bay / the vessel')}</li><li>${external(rootURL+'/crew/jupiterfox.html',"The Navigator's current page")}</li><li>${external(rootURL+'/crew/ruby-fox.html','Ruby Fox / the shrine')}</li><li>${external(rootURL+'/crew/desenrascanco-do-atlan.html','The Chief Engineer / material systems')}</li><li>${external(rootURL+'/crew/sandhivela.html','Sandhivela / junctions')}</li><li>${external('https://templeos.org/','TempleOS / Terry A. Davis')}</li><li>${external('https://templeos.info/Wb/Kernel/FontStd.HC.HTML','Original TempleOS bitmap font')}</li></ul><h3>CREDITS</h3><p>TempleOS and its font table are public domain. Vector font conversion and all pixel drawings were made for this site. DeviationShrineOS is an unofficial creative homage.</p><p class="magenta">An operating system for leaving something open.</p></div>`,status:()=>footer('SOURCES + CREDITS + THE PLAIN CHANNEL')}
};

function crewDetails(){const p=CREW[state.crew];return `${iconHTML(p.icon,'crew-portrait')}<div class="eyebrow">CREW NODE ${String(state.crew+1).padStart(2,'0')}</div><h2 class="app-title">${p.name}</h2><div class="magenta">${p.role}</div><p class="crew-status">${p.status}</p><p>${p.bio}</p><p class="crew-comment">${p.note}</p><p class="disclosure">Terminal aside / written for this desktop.</p><p style="margin-top:17px">${external(rootURL+p.url,'Read the original plate')}</p>`}
function roomDetails(){const r=ROOMS[state.room];return `<div class="room-number">COMPARTMENT ${String(state.room+1).padStart(2,'0')}</div><h3>${r.name}</h3><div class="magenta">${r.status}</div><p>${r.text}</p>${r.action?`<button class="btn" data-action="enter-room">${r.label}</button>`:'<p class="hatch-block">An unentered room<br>is still a room.</p>'}`}
function paintIcons(root=document){$$('[data-icon]',root).forEach(c=>icon(c,c.dataset.icon))}
function openApp(id,focus=true){
 if(!Object.hasOwn(APPS,id)){notify(`No program named ${id}.`);return}
 hideMenu();if(windows.has(id)){const win=windows.get(id);win.hidden=false;activate(id);if(focus&&id==='shell')$('#shell-input')?.focus({preventScroll:true});return}
 const a=APPS[id],win=document.createElement('section');win.className='window';win.dataset.id=id;win.setAttribute('aria-label',a.title);win.tabIndex=-1;Object.assign(win.style,{left:a.x+'px',top:a.y+'px',width:a.w+'px',height:a.h+'px'});
 win.innerHTML=`<header class="window-header"><span class="window-glyph">${id==='oracle'?'*':id==='shell'?'>':'='}</span><span class="window-title">${a.title}</span><div class="window-controls"><button data-action="minimize" aria-label="Minimize ${a.task}" title="Minimize">_</button><button data-action="maximize" aria-label="Maximize ${a.task}" title="Maximize">[]</button><button data-action="close" aria-label="Close ${a.task}" title="Close">x</button></div></header><div class="window-body">${a.content()}</div><footer class="window-footer">${a.status()}</footer>`;
 $('#window-layer').append(win);windows.set(id,win);paintIcons(win);wireWindow(win,id);activate(id);if(id==='atlas')mapBackground($('#deck-map'));if(id==='workshop')runCode();drawOnce();if(focus){if(id==='shell')$('#shell-input').focus({preventScroll:true});else win.focus({preventScroll:true})}tone(id==='oracle'?694:360,.035);
}
function activate(id){if(!windows.has(id))return;activeId=id;for(const[k,w]of windows)w.classList.toggle('active',k===id);const w=windows.get(id);w.style.zIndex=++topZ;renderTasks()}
function renderTasks(){$('#tasks').innerHTML=[...windows].map(([id,w])=>`<button data-task="${id}" class="${activeId===id&&!w.hidden?'selected':''}" aria-label="Switch to ${APPS[id].task}" title="${APPS[id].task}">${APPS[id].task}</button>`).join('')}
function activateNext(){const next=[...windows].filter(([,w])=>!w.hidden).sort((a,b)=>Number(b[1].style.zIndex)-Number(a[1].style.zIndex))[0];if(next)activate(next[0]);else {activeId='';renderTasks()}}
function closeApp(id){const w=windows.get(id);if(w){w.remove();windows.delete(id);activateNext()}}
function toggleMax(id){const w=windows.get(id);if(!w)return;if(w.dataset.restore){Object.assign(w.style,JSON.parse(w.dataset.restore));delete w.dataset.restore}else{w.dataset.restore=JSON.stringify({left:w.style.left,top:w.style.top,width:w.style.width,height:w.style.height});Object.assign(w.style,{left:'2px',top:'2px',width:'636px',height:'417px'})}}
function wireWindow(win,id){
 win.addEventListener('pointerdown',()=>{if(activeId!==id)activate(id)});
 const header=$('.window-header',win);header.addEventListener('dblclick',e=>{if(!e.target.closest('button'))toggleMax(id)});
 header.addEventListener('pointerdown',e=>{
   if(e.target.closest('button')||win.dataset.restore||e.button!==0)return;
   e.preventDefault();const startX=e.clientX,startY=e.clientY,left=parseFloat(win.style.left),top=parseFloat(win.style.top);header.setPointerCapture(e.pointerId);
   const move=ev=>{const x=left+(ev.clientX-startX)/scale,y=top+(ev.clientY-startY)/scale;win.style.left=Math.round(Math.max(0,Math.min(640-win.offsetWidth,x)))+'px';win.style.top=Math.round(Math.max(0,Math.min(405,y)))+'px'};
   const stop=()=>{header.removeEventListener('pointermove',move);header.removeEventListener('pointerup',stop);header.removeEventListener('pointercancel',stop)};
   header.addEventListener('pointermove',move);header.addEventListener('pointerup',stop);header.addEventListener('pointercancel',stop);
 });
 if(id==='shell'){
   $('.shell-form',win).addEventListener('submit',e=>{e.preventDefault();const input=$('#shell-input'),raw=input.value.trim();if(!raw)return;input.value='';HISTORY.push(raw);historyCursor=HISTORY.length;printShell('C:/Home> '+raw,'accent');runShell(raw)});
   $('#shell-input').addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyCursor=Math.max(0,Math.min(HISTORY.length,historyCursor+(e.key==='ArrowUp'?-1:1)));e.target.value=HISTORY[historyCursor]||''}if(e.key==='Tab'){const raw=e.target.value;const options=['help','ls','open','oracle','atlas','crew','workshop','logbook','echo','log','date','clear','detune','reboot'];const hits=options.filter(s=>s.startsWith(raw));if(hits.length===1&&raw){e.preventDefault();e.target.value=hits[0]+' '}}});
 }
 if(id==='oracle')$('#oracle-question').addEventListener('input',e=>state.question=e.target.value);
 if(id==='logbook'){$('#log-editor').value=state.log;$('#log-editor').addEventListener('input',e=>{state.log=e.target.value;updateLog(persist())});}
 if(id==='workshop'){
   $('#code-editor').value=state.code;
   $('#code-editor').addEventListener('input',e=>{state.code=e.target.value;const ok=persist();$('#code-status').textContent=ok?'LOCAL AUTOSAVE':'SESSION ONLY'});
   $('#code-editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,a=t.selectionStart,b=t.selectionEnd;t.setRangeText('  ',a,b,'end');state.code=t.value;persist()}});
   $('#example-select').addEventListener('change',e=>{const value=e.target.value;if(!Object.hasOwn(EXAMPLES,value))return;state.code=EXAMPLES[value];$('#code-editor').value=state.code;persist();runCode();e.target.value=''});
 }
}
function random(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296}
function cast(){let next=getFragment(random);for(let i=0;i<5&&next.text===state.oracle?.text;i++)next=getFragment(random);state.oracle=next;state.casts++;if($('#oracle-reading')){$('#oracle-reading').textContent=next.text;$('#oracle-residue').textContent=next.residue;$('#cast-number').textContent='#'+String(state.casts).padStart(3,'0');$('[data-action="keep-fragment"]').disabled=false}tone(694,.09);return next}
function appendLog(text){state.log+=(state.log?'\n\n':'')+text;const ok=persist();if($('#log-editor')){$('#log-editor').value=state.log;updateLog(ok)}return ok}
function updateLog(ok){if(!$('#log-status'))return;$('#log-status').textContent=ok?'Saved on this device. Export a copy to carry it elsewhere.':'Storage unavailable. Your words remain in this session; export to keep them.';$('#log-count').textContent=state.log.length+' chars'}
function saveFragment(){if(!state.oracle)return;const text=`[DEVIATION ${String(state.casts).padStart(3,'0')} / ${new Date().toISOString()}]\n${state.question?'Carrying: '+state.question+'\n':''}${state.oracle.text}\n${state.oracle.residue}\nOrigin: local chance composition.`;const ok=appendLog(text);notify(ok?'Fragment kept in your logbook.':'Fragment kept for this session. Export your log to save it.');tone(523)}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function runCode(){const canvas=$('#offering-canvas');if(!canvas)return;try{const ops=parseProgram(state.code);$('#program-output').textContent=executeProgram(canvas,ops);$('#program-output').style.color='#555';tone(523,.03)}catch(e){$('#program-output').textContent=e.message;$('#program-output').style.color='#aa0000'}}
function printShell(text,cls=''){if(!windows.has('shell'))openApp('shell',false);const output=$('.shell-output'),line=document.createElement('div');line.className='shell-line '+cls;line.textContent=text;output.append(line);while(output.children.length>150)output.firstChild.remove();const body=$('.window-body',windows.get('shell'));body.scrollTop=body.scrollHeight}
function runShell(raw){const {command,args}=parseShell(raw);switch(command){
 case'help':printShell('help  ls  open <program>  oracle  atlas  crew\nworkshop  logbook  echo <words>  log <words>\ndate  detune  clear  reboot\nTry: open atlas  |  log a small impossible thing');break;
 case'ls':case'dir':printShell('C:/Home/\n  oracle     SHRINE.HC\n  atlas      ATLAS.DD\n  crew       CREW.DD\n  workshop   OFFERING.DC\n  logbook    SHIPSLOG.TXT\n  about      SHIPSPAPERS.DD');break;
 case'open':if(Object.hasOwn(APPS,args.toLowerCase()))openApp(args.toLowerCase());else printShell(args?'No program: '+args:'Usage: open atlas','error');break;
 case'oracle':{const f=cast();printShell(f.text+'\n'+f.residue,'accent');break}
 case'home':case'atlas':case'crew':case'workshop':case'logbook':case'about':openApp(command);break;
 case'echo':printShell(args);break;
 case'log':if(!args)printShell('Usage: log <words to keep>','muted');else printShell(appendLog(`[${new Date().toISOString()}] ${args}`)?'Kept in the logbook.':'Kept for this session. Export the log to save it.','accent');break;
 case'date':printShell(new Date().toLocaleString()+' / local ship time');break;
 case'detune':toggleDetune();printShell('Stabilizers: '+(state.detuned?'DETUNED':'FREE DRIFT')+' / simulated');break;
 case'clear':case'cls':$('.shell-output').replaceChildren();break;
 case'reboot':reboot();break;
 case'whoami':printShell('A visitor with an open hatch.\nNo office assigned.');break;
 case'soup':printShell('Almost ready. This is a standing state.','accent');break;
 case'seven':printShell('the galley and i are handling this. - navigator','accent');break;
 case'god':printShell('The shrine has put to sea. Try oracle.','accent');break;
 case'cat':printShell('The fox disputes this classification.','accent');break;
 default:printShell(`Unknown command: ${command}. Type help.`,'error');
}}
function toggleDetune(){state.detuned=!state.detuned;if($('#detune-label'))$('#detune-label').textContent=state.detuned?'DETUNED':'FREE DRIFT';drawOnce();tone(state.detuned?623:694)}
function hideMenu(){$('#start-menu').hidden=true;$('#temple-menu-button').setAttribute('aria-expanded','false')}
function toggleMenu(){const m=$('#start-menu');m.hidden=!m.hidden;$('#temple-menu-button').setAttribute('aria-expanded',String(!m.hidden));if(!m.hidden)$('button',m).focus({preventScroll:true})}
function updateControls(){const b=$('.sound-indicator');b.textContent='SND:'+(state.sound?'ON':'OFF');b.setAttribute('aria-label','Turn sound '+(state.sound?'off':'on'));$('#motion-button').textContent='MOTION '+(state.motion?'ON':'OFF');$('#motion-button').setAttribute('aria-pressed',String(!state.motion));document.body.classList.toggle('reduced-motion',!state.motion)}
function layout(){const viewport=$('#viewport'),available=Math.max(180,viewport.clientWidth-6),isSmall=window.innerWidth<700;const heightFit=Math.max(240,window.innerHeight-(isSmall?200:177));scale=state.scale==='fit'?Math.min(2,available/640,heightFit/480):Number(state.scale);const w=640*scale,h=480*scale;$('#screen-frame').style.width=w+'px';$('#screen-frame').style.height=h+'px';$('#screen').style.transform=`scale(${scale})`;document.documentElement.style.setProperty('--frame-width',w+'px');$('#scale-button').textContent=state.scale==='fit'?'FIT':state.scale+'X';viewport.scrollLeft=0}
function initialDesktop(){for(const w of windows.values())w.remove();windows.clear();topZ=10;['home','vessel','telemetry','shell'].forEach(id=>openApp(id,false));activate('home');drawOnce()}
function reboot(){hideMenu();const boot=$('#boot');boot.hidden=false;tone(220,.12);setTimeout(()=>{initialDesktop();boot.hidden=true;notify('Display rebooted. Your log and code are retained.');tone(440,.08)},state.motion?1200:100)}
function drawOnce(){$$('[data-draw="vessel"]').forEach(c=>vessel(c,elapsed));$$('[data-draw="wave"]').forEach(c=>waveform(c,elapsed,state.detuned));$$('[data-draw="shrine"]').forEach(c=>shrine(c,elapsed))}
function animate(time){if(state.motion&&time-lastFrame>70&&!document.hidden){elapsed+=Math.min((time-lastFrame)/1000,.12);lastFrame=time;drawOnce()}else if(!state.motion)lastFrame=time;requestAnimationFrame(animate)}

document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b){if(!e.target.closest('#start-menu'))hideMenu();return}
 if(b.dataset.open){openApp(b.dataset.open);return}
 if(b.dataset.task){const w=windows.get(b.dataset.task);w.hidden=false;activate(b.dataset.task);return}
 if(b.dataset.crew!==undefined){state.crew=Number(b.dataset.crew);$('#crew-details').innerHTML=crewDetails();$$('[data-crew]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.crew)===state.crew));paintIcons($('#crew-details'));if(state.crew===2)tone(777,.06);return}
 if(b.dataset.room!==undefined){state.room=Number(b.dataset.room);$('#atlas-details').innerHTML=roomDetails();$$('[data-room]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.room)===state.room));tone(300+state.room*60,.035);return}
 const id=b.closest('.window')?.dataset.id;
 switch(b.dataset.action){
 case'menu':toggleMenu();break;
 case'close':closeApp(id);break;
 case'minimize':windows.get(id).hidden=true;activateNext();break;
 case'maximize':toggleMax(id);break;
 case'cast':cast();break;
 case'keep-fragment':saveFragment();break;
 case'enter-room':{const r=ROOMS[state.room];if(r.crew!==undefined)state.crew=r.crew;const alreadyCrew=windows.has('crew');openApp(r.action);if(r.crew!==undefined&&alreadyCrew){$('#crew-details').innerHTML=crewDetails();$$('[data-crew]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.crew)===state.crew));paintIcons($('#crew-details'))}break}
 case'detune':toggleDetune();break;
 case'run-code':runCode();break;
 case'export-code':download('Offering.DC',state.code);notify('Offering exported.');break;
 case'export-log':download('DeviationShrineOS-ShipsLog.txt',state.log);notify('Logbook exported.');break;
 case'timestamp':{const t=$('#log-editor'),date=`\n[SHIP'S DATE / ${new Date().toISOString()}]\n`;t.setRangeText(date,t.selectionStart,t.selectionEnd,'end');state.log=t.value;updateLog(persist());t.focus({preventScroll:true});break}
 case'reboot':reboot();break;
 case'sound':state.sound=!state.sound;updateControls();tone(694,.06);break;
 case'motion':state.motion=!state.motion;persist();updateControls();drawOnce();break;
 case'scale':state.scale=state.scale==='fit'?'1':state.scale==='1'?'2':'fit';layout();break;
 case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else notify('Fullscreen is unavailable in this browser.')}catch{notify('Fullscreen is unavailable in this browser.')}break;
 }
});
document.addEventListener('keydown',e=>{
 const keys={F1:'help',F2:'oracle',F3:'atlas',F4:'crew',F5:'workshop',F6:'logbook',F7:'shell'};
 if(keys[e.key]){e.preventDefault();if(e.key==='F5'&&activeId==='workshop')runCode();else openApp(keys[e.key]);return}
 if(e.key==='Escape'){e.preventDefault();if(!$('#start-menu').hidden)hideMenu();else if(activeId)closeApp(activeId)}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&['logbook','workshop'].includes(activeId)){e.preventDefault();persist();notify(storageOK?'Saved in this browser.':'Storage unavailable. Use Export to keep this file.')}
});
window.addEventListener('resize',layout);document.addEventListener('fullscreenchange',layout);
function updateClock(){$('#clock').textContent=new Date().toLocaleTimeString('en-GB',{hour12:false})}
initialDesktop();layout();updateControls();updateClock();setInterval(updateClock,1000);requestAnimationFrame(animate);
document.fonts.ready.then(()=>drawOnce());
